runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const root='/var/lib/news-flow/qc-remaining28-20261122',registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},pool,network,allowedDomains:[...registry.allowedDomains,'api.biggo.com'],siteCooldown:false,maxWireRequests:4}),r={at:new Date().toISOString(),checks:[]};try{for(const path of ['/news/home/list','/news/list']){const url='https://api.biggo.com/api/v1/finance'+path+'?region=us',p=await driver.get('qc28-biggo-public-api',url,registry.sources.get('finance.biggo.com').config,[],{reviewFailed:true,taskRole:'publisher_dependency',headers:{Accept:'application/json'}}),o={url,statusCode:p.statusCode,error:p.error};if(p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));if(!p.error){try{const data=JSON.parse(p.html);o.topKeys=Object.keys(data);o.fields=[];let total=0;function walk(v){if(!v||typeof v!=='object'||++total>3000)return;if(Array.isArray(v)){v.slice(0,5).forEach(walk);return;}if(v.id&&v.title&&o.fields.length<4)o.fields.push({id:v.id,keys:Object.keys(v),publication:v.published_at||v.publish_time||v.created_at,bodyChars:(v.content||v.body||v.articleBody||'').length});for(const x of Object.values(v))if(x&&typeof x==='object')walk(x);}walk(data);}catch{}}}r.checks.push(o);console.log(JSON.stringify(o));}fs.writeFileSync(root+'/biggo-public-api.json',JSON.stringify(r,null,2));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-remaining28-20261122/biggo-public-api.json "$upload_dir/.qc28-biggo-public-api.json"
